<script setup>
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import Layout from '../../layouts/main.vue'
import RiskBadge from '../../components/social-work/risk-badge.vue'
import ProtectionBadge from '../../components/social-work/protection-badge.vue'
import CaseWorkspace from '../../components/social-work/case-workspace.vue'
import StudentSupportWorkspace from '../../components/social-work/student-support-workspace.vue'
import JunaebWorkspace from '../../components/social-work/junaeb-workspace.vue'
import HealthWorkspace from '../../components/social-work/health-workspace.vue'
import PickupRestrictionsWorkspace from '../../components/social-work/pickup-restrictions-workspace.vue'
import ReferralWorkspace from '../../components/social-work/referral-workspace.vue'
import DashboardCharts from '../../components/social-work/dashboard-charts.vue'
import CalendarWorkspace from '../../components/social-work/calendar-workspace.vue'
import { useSocialWork } from '../../composables/useSocialWork'
import { downloadSocialCaseMaster, downloadSocialCsv } from '../../utils/social-work-export'

const route = useRoute(); const router = useRouter(); const api = reactive(useSocialWork())
const catalogs = ref({ case_statuses: [], risk_levels: [], priorities: [], confidentiality: [], courses: [], professionals: [], protocols: [] })
const data = ref(null); const pagination = ref({}); const search = ref(''); const filter = reactive({ status: '', risk_level: '', course_section_id: '' }); const success = ref('')
const tabs = [
  ['dashboard','Resumen','bx-grid-alt','/social-work','social_work.dashboard.view'], ['students','Situación social','bx-group','/social-work/students','social_work.students.view'], ['cases','Casos y atenciones','bx-folder-open','/social-work/cases','social_work.cases.view'], ['alerts','Alertas','bx-bell','/social-work/alerts','social_work.alerts.manage'], ['referrals','Derivaciones','bx-transfer','/social-work/referrals','social_work.referrals.submit'], ['junaeb','JUNAEB','bx-package','/social-work/junaeb','social_work.junaeb.manage'], ['health','Salud','bx-plus-medical','/social-work/health','social_work.medical.manage'], ['restrictions','Restricciones de retiro','bx-shield-quarter','/social-work/pickup-restrictions','social_work.pickup_restrictions.manage'], ['reports','Informes','bx-file','/social-work/reports','social_work.reports.create'], ['calendar','Calendario','bx-calendar','/social-work/calendar','social_work.dashboard.view'], ['settings','Configuración','bx-cog','/social-work/settings','social_work.templates.manage'], ['audit','Auditoría','bx-history','/social-work/audit','social_work.audit.view']
]
const visibleTabs = computed(() => tabs.filter(tab => api.can(tab[4])))
const pathSection = computed(() => { const p=route.path; if(route.params.caseId)return 'case-detail'; if(route.params.studentId)return 'student-detail'; if(p.endsWith('/new'))return 'case-new'; return tabs.find(t=>p===t[3])?.[0] || (p.includes('/protocol')?'settings':p.includes('/interview')||p.includes('/actions')?'cases':'dashboard') })
const title = computed(() => ({dashboard:'Panel de Trabajo Social',students:'Matriz social de alumnas','student-detail':'Ficha social del estudiante',cases:'Casos y fichas de atención','case-new':'Crear caso social','case-detail':'Ficha de atención',alerts:'Centro de alertas',referrals:'Derivaciones',junaeb:'JUNAEB y programas complementarios',health:'Salud desde la ficha estudiantil',restrictions:'Restricciones de retiro',reports:'Informes sociales',calendar:'Calendario social',settings:'Plantillas y protocolos',audit:'Auditoría de accesos y cambios'}[pathSection.value]))
const caseForm = reactive({primary_student_id:'',student_ids:[],title:'',reason:'',origin:'derivacion',case_type:'general',priority:'media',risk_level:'sin_evaluar',confidentiality:'restringido',status:'borrador',responsible_user_id:'',initial_description:'',initial_safeguards:'',next_milestone:'',due_at:''})
const actionForm = reactive({kind:'accion',type:'seguimiento',activity_date:new Date().toISOString().slice(0,10),starts_at:'',objective:'',description:'',result:'',agreements:'',next_action:'',due_at:'',status:'finalizada',confidentiality:'restringido',participants:[],commitments:[]})
const referralForm = reactive({student_profile_id:'',referral_date:new Date().toISOString().slice(0,10),source_unit:'docente',reason:'',description:'',urgency:'normal',immediate_risk:false,status:'enviada',confidentiality:'restringido'})
const studentsForSelect = ref([])
const metrics = computed(()=>data.value?.data || {})
const rows = computed(()=>data.value?.data || (Array.isArray(data.value)?data.value:[]))
const caseData = computed(()=>data.value?.data || null)
const studentName = (s)=>s?.registered_name_resolved || s?.registered_name || [s?.first_name,s?.last_name].filter(Boolean).join(' ')
const statusLabel = (v)=>String(v||'').replaceAll('_',' ')
const fmt = (v)=>v ? new Intl.DateTimeFormat('es-CL',{dateStyle:'medium'}).format(new Date(v)) : '—'

async function loadCatalogs(){ try{ catalogs.value=(await api.get('/catalogs')).data }catch{} }
async function loadStudentsForSelect(){
  try{
    const collected=[]; let page=1; let lastPage=1
    do { const response=await api.get(`/students?per_page=100&page=${page}`); collected.push(...(response.data||[])); lastPage=response.last_page||1; page+=1 } while(page<=lastPage)
    studentsForSelect.value=collected
  }catch{ studentsForSelect.value=[] }
}
async function load(page=1){ success.value=''; const q=new URLSearchParams({page,per_page:20}); if(search.value)q.set('search',search.value); Object.entries(filter).forEach(([k,v])=>v&&q.set(k,v));
  let endpoint='/dashboard'; const s=pathSection.value
  if(['students','cases','case-new','case-detail','referrals','junaeb','health','restrictions'].includes(s)){data.value=null;pagination.value={};return}
  if(s==='students')endpoint=`/students?${q}`; if(s==='student-detail')endpoint=`/students/${route.params.studentId}`; if(s==='cases')endpoint=`/cases?${q}`; if(s==='case-detail')endpoint=`/cases/${route.params.caseId}`; if(s==='alerts')endpoint=`/alerts?${q}`; if(s==='referrals')endpoint=`/referrals?${q}`; if(s==='junaeb')endpoint=`/junaeb/benefits?${q}`; if(s==='health')endpoint=`/medical-services?${q}`; if(s==='reports')endpoint=`/reports?${q}`; if(s==='calendar')endpoint='/calendar'; if(s==='settings')endpoint='/form-templates'; if(s==='audit')endpoint=`/audit?${q}`
  if(s==='case-new'){data.value=null;return} try{data.value=await api.get(endpoint); pagination.value={current_page:data.value.current_page,last_page:data.value.last_page,total:data.value.total}}catch{data.value=null}
}
async function createCase(){ const payload={...caseForm,primary_student_id:Number(caseForm.primary_student_id),responsible_user_id:caseForm.responsible_user_id?Number(caseForm.responsible_user_id):null,due_at:caseForm.due_at||null}; try{const r=await api.post('/cases',payload); router.push(`/social-work/cases/${r.data.id}`)}catch{} }
async function createAction(){ try{await api.post(`/cases/${route.params.caseId}/interventions`,{...actionForm,starts_at:actionForm.starts_at||null,due_at:actionForm.due_at||null}); success.value='Intervención registrada correctamente.'; await load()}catch{} }
async function createReferral(){ try{await api.post('/referrals',{...referralForm,student_profile_id:Number(referralForm.student_profile_id)}); success.value='Derivación enviada sin conceder acceso al caso.'; referralForm.reason='';referralForm.description='';await load()}catch{} }
async function closeCase(){ const conclusion=window.prompt('Conclusión final obligatoria'); if(!conclusion)return; try{if(caseData.value.status!=='pendiente_cierre')await api.post(`/cases/${route.params.caseId}/change-status`,{status:'pendiente_cierre',reason:'Preparación de cierre profesional'});await api.post(`/cases/${route.params.caseId}/close`,{closure_conclusion:conclusion,closure_result:'intervencion_finalizada',closure_reason:'Cierre profesional',final_risk_level:caseData.value.risk_level});success.value='Caso cerrado y trazabilidad conservada.';await load()}catch{} }
async function generateReport(){ try{await api.post(`/cases/${route.params.caseId}/master-report`,{sections:['resumen','estados','intervenciones','protocolos','alertas','derivaciones','cierres']});success.value='Borrador de ficha maestra generado para revisión humana.';await load()}catch{} }
function exportList(){ downloadSocialCsv(rows.value, `trabajo-social-${pathSection.value}`) }
function go(path){if(path!==route.path)router.push(path)}
async function initializeSection(){
  const section=pathSection.value; const tasks=[load()]
  if(api.can('social_work.dashboard.view') && (['dashboard','cases','case-new','case-detail','referrals','junaeb','restrictions'].includes(section) || !catalogs.value.case_statuses.length))tasks.push(loadCatalogs())
  if(['cases','case-new','case-detail','junaeb','restrictions'].includes(section) && api.can('social_work.students.view'))tasks.push(loadStudentsForSelect())
  await Promise.allSettled(tasks)
}
watch(()=>route.fullPath,initializeSection); onMounted(initializeSection)
</script>

<template>
<Layout><div class="sw-page container-fluid py-3">
  <header class="sw-header mb-3"><div><p class="sw-kicker mb-1">Gestión confidencial y trazable</p><h1>{{ title }}</h1><p class="mb-0 text-muted">Información sensible visible únicamente según permisos y asignación.</p></div><button v-if="api.can('social_work.cases.create') && pathSection==='dashboard'" class="btn btn-primary" @click="go('/social-work/cases/new')"><i class="bx bx-plus"></i> Nuevo caso</button></header>
  <nav class="sw-tabs mb-3" aria-label="Secciones de Trabajo Social"><button v-for="tab in visibleTabs" :key="tab[0]" :class="{active:pathSection===tab[0]}" @click="go(tab[3])"><i class="bx" :class="tab[2]"></i>{{tab[1]}}</button></nav>
  <div v-if="api.error" class="alert alert-danger d-flex align-items-center justify-content-between gap-2"><span><i class="bx bx-error-circle"></i> {{api.error}}</span><button type="button" class="btn btn-sm btn-outline-danger" @click="load()">Reintentar</button></div><div v-if="success" class="alert alert-success"><i class="bx bx-check-circle"></i> {{success}}</div>
  <div v-if="api.loading" class="sw-loading"><span class="spinner-border spinner-border-sm"></span> Cargando información autorizada…</div>

  <CaseWorkspace v-else-if="['cases','case-new','case-detail'].includes(pathSection)" :students="studentsForSelect" :catalogs="catalogs" :initial-case-id="route.params.caseId" :open-create="pathSection === 'case-new'" @route-reset="router.replace('/social-work/cases')" />
  <StudentSupportWorkspace v-else-if="pathSection === 'students'" :catalogs="catalogs" @open-student="id => go(`/social-work/students/${id}`)" />
  <ReferralWorkspace v-else-if="pathSection === 'referrals'" :catalogs="catalogs" @open-case="id => go(`/social-work/cases/${id}`)" />
  <JunaebWorkspace v-else-if="pathSection === 'junaeb'" :students="studentsForSelect" :catalogs="catalogs" />
  <HealthWorkspace v-else-if="pathSection === 'health'" />
  <PickupRestrictionsWorkspace v-else-if="pathSection === 'restrictions'" :students="studentsForSelect" />
  <CalendarWorkspace v-else-if="pathSection === 'calendar'" :events="data?.data || []" @open="go" />

  <template v-else-if="pathSection==='dashboard'">
    <section class="metric-grid"><article v-for="m in [['Casos activos',metrics.active_cases,'bx-folder-open'],['Alertas nuevas',metrics.new_alerts,'bx-bell'],['Alertas críticas',metrics.critical_alerts,'bx-shield-x'],['Derivaciones pendientes',metrics.pending_referrals,'bx-transfer'],['Casos vencidos',metrics.overdue_cases,'bx-time-five'],['Sin actividad',metrics.inactive_cases,'bx-pause-circle'],['JUNAEB pendiente',metrics.pending_junaeb,'bx-package'],['Certificados por vencer',metrics.expiring_certificates,'bx-plus-medical']]" :key="m[0]" class="metric-card"><i class="bx" :class="m[2]"></i><strong>{{m[1]??0}}</strong><span>{{m[0]}}</span></article></section>
    <DashboardCharts :statuses="metrics.cases_by_status" :risks="metrics.cases_by_risk" />
  </template>

  <template v-else-if="['alerts','reports','audit'].includes(pathSection)">
    <div class="d-flex justify-content-end mb-2"><button v-if="api.can('social_work.reports.export')" class="btn btn-sm btn-outline-secondary" @click="exportList"><i class="bx bx-spreadsheet"></i> Exportar Excel/CSV autorizado</button></div>
    <section class="sw-card"><div class="filter-bar"><div class="input-group"><span class="input-group-text"><i class="bx bx-search"></i></span><input v-model="search" class="form-control" placeholder="Buscar por nombre, RUT o código" @keyup.enter="load()"></div><select v-if="['cases','alerts','referrals'].includes(pathSection)" v-model="filter.status" class="form-select"><option value="">Todos los estados</option><option v-for="s in catalogs.case_statuses" :key="s" :value="s">{{statusLabel(s)}}</option></select><select v-if="['students','cases'].includes(pathSection)" v-model="filter.risk_level" class="form-select"><option value="">Todo riesgo</option><option v-for="r in catalogs.risk_levels" :key="r" :value="r">{{statusLabel(r)}}</option></select><button class="btn btn-outline-primary" @click="load()">Aplicar</button><button v-if="pathSection==='referrals'" class="btn btn-primary" data-bs-toggle="collapse" data-bs-target="#referralForm">Nueva derivación</button></div>
      <div v-if="pathSection==='referrals'" id="referralForm" class="collapse sw-inline-form"><div class="row g-2"><div class="col-md-4"><label>Estudiante</label><select v-model="referralForm.student_profile_id" class="form-select"><option value="">Selecciona</option><option v-for="s in studentsForSelect" :key="s.id" :value="s.id">{{studentName(s)}} · {{s.rut}}</option></select></div><div class="col-md-4"><label>Unidad derivante</label><input v-model="referralForm.source_unit" class="form-control"></div><div class="col-md-4"><label>Urgencia propuesta</label><select v-model="referralForm.urgency" class="form-select"><option>normal</option><option>alta</option><option>urgente</option></select></div><div class="col-12"><label>Motivo</label><input v-model="referralForm.reason" class="form-control"></div><div class="col-12"><label>Descripción</label><textarea v-model="referralForm.description" class="form-control" rows="3"></textarea></div><div class="col-12"><button class="btn btn-primary" @click="createReferral">Enviar derivación</button></div></div></div>
      <div class="table-responsive"><table class="table align-middle"><thead><tr v-if="pathSection==='students'"><th>Estudiante</th><th>Curso</th><th>Indicadores</th><th>Casos</th><th>Riesgo</th><th></th></tr><tr v-else-if="pathSection==='cases'"><th>Código / caso</th><th>Estudiante</th><th>Estado</th><th>Riesgo</th><th>Responsable</th><th></th></tr><tr v-else><th>Registro</th><th>Estudiante / caso</th><th>Estado</th><th>Fecha</th><th></th></tr></thead><tbody>
        <tr v-for="item in rows" :key="item.id">
          <template v-if="pathSection==='students'"><td><strong>{{studentName(item)}}</strong><small>{{item.rut||'Sin RUT'}}</small></td><td>{{item.current_enrollment?.course_section?.display_name||item.current_enrollment?.snapshot_course_display_name||'Sin curso'}}</td><td><span v-if="item.is_pie_participant" class="soft-badge">PIE</span> <ProtectionBadge :count="item.active_protection_measures_count"/></td><td>{{item.active_cases_count}}</td><td><RiskBadge :level="item.latest_social_case?.risk_level"/></td><td><button class="btn btn-sm btn-outline-primary" @click="go(`/social-work/students/${item.id}`)">Abrir ficha</button></td></template>
          <template v-else-if="pathSection==='cases'"><td><strong>{{item.code}}</strong><small>{{item.title}}</small></td><td>{{studentName(item.student)}}</td><td><span class="soft-badge">{{statusLabel(item.status)}}</span></td><td><RiskBadge :level="item.risk_level"/></td><td>{{item.responsible?.name||'Sin asignar'}}</td><td><button class="btn btn-sm btn-outline-primary" @click="go(`/social-work/cases/${item.id}`)">Abrir</button></td></template>
          <template v-else><td><strong>{{item.type||item.title||item.reason||item.benefit_type?.name||item.service_type}}</strong><small>{{item.code||item.deduplication_key||''}}</small></td><td>{{studentName(item.student)||item.case?.code||'—'}}</td><td><span class="soft-badge">{{statusLabel(item.status)}}</span></td><td>{{fmt(item.alerted_at||item.referral_date||item.created_at||item.referred_on)}}</td><td></td></template>
        </tr><tr v-if="!rows.length"><td colspan="6" class="empty">No hay registros para los filtros seleccionados.</td></tr></tbody></table></div>
      <div v-if="pagination.last_page>1" class="pager"><button class="btn btn-sm btn-outline-secondary" :disabled="pagination.current_page<=1" @click="load(pagination.current_page-1)">Anterior</button><span>Página {{pagination.current_page}} de {{pagination.last_page}}</span><button class="btn btn-sm btn-outline-secondary" :disabled="pagination.current_page>=pagination.last_page" @click="load(pagination.current_page+1)">Siguiente</button></div>
    </section>
  </template>

  <form v-else-if="pathSection==='case-new'" class="sw-card" @submit.prevent="createCase"><div class="section-title"><h2>Antecedentes de apertura</h2><span>Los relatos no aparecerán en notificaciones generales.</span></div><div class="row g-3"><div class="col-lg-6"><label>Estudiante principal *</label><select v-model="caseForm.primary_student_id" class="form-select" required><option value="">Selecciona estudiante</option><option v-for="s in studentsForSelect" :key="s.id" :value="s.id">{{studentName(s)}} · {{s.rut||'Sin RUT'}}</option></select></div><div class="col-lg-6"><label>Profesional responsable</label><select v-model="caseForm.responsible_user_id" class="form-select"><option value="">Sin asignar</option><option v-for="u in catalogs.professionals" :key="u.id" :value="u.id">{{u.name}}</option></select></div><div class="col-md-8"><label>Título breve *</label><input v-model="caseForm.title" class="form-control" required maxlength="255"></div><div class="col-md-4"><label>Motivo *</label><input v-model="caseForm.reason" class="form-control" required></div><div class="col-md-4"><label>Prioridad *</label><select v-model="caseForm.priority" class="form-select"><option v-for="v in catalogs.priorities" :key="v">{{v}}</option></select></div><div class="col-md-4"><label>Riesgo inicial *</label><select v-model="caseForm.risk_level" class="form-select"><option v-for="v in catalogs.risk_levels" :key="v">{{v}}</option></select></div><div class="col-md-4"><label>Confidencialidad *</label><select v-model="caseForm.confidentiality" class="form-select"><option v-for="v in catalogs.confidentiality" :key="v">{{statusLabel(v)}}</option></select></div><div class="col-12"><label>Descripción inicial</label><textarea v-model="caseForm.initial_description" class="form-control" rows="4"></textarea></div><div class="col-12"><label>Medidas de resguardo iniciales</label><textarea v-model="caseForm.initial_safeguards" class="form-control" rows="2"></textarea></div><div class="col-md-8"><label>Próximo hito</label><input v-model="caseForm.next_milestone" class="form-control"></div><div class="col-md-4"><label>Fecha límite</label><input v-model="caseForm.due_at" type="datetime-local" class="form-control"></div><div class="col-12 d-flex justify-content-end gap-2"><button type="button" class="btn btn-light" @click="go('/social-work/cases')">Cancelar</button><button class="btn btn-primary">Crear caso</button></div></div></form>

  <template v-else-if="pathSection==='case-detail' && caseData"><section class="case-hero"><div><span class="case-code">{{caseData.code}}</span><h2>{{caseData.title}}</h2><p>{{studentName(caseData.student)}} · {{caseData.course_section?.display_name||'Sin curso'}}</p></div><div class="case-facts"><span><small>Estado</small>{{statusLabel(caseData.status)}}</span><span><small>Riesgo</small><RiskBadge :level="caseData.risk_level"/></span><span><small>Prioridad</small>{{statusLabel(caseData.priority)}}</span><span><small>Responsable</small>{{caseData.responsible?.name||'Sin asignar'}}</span><span><small>Abierto</small>{{fmt(caseData.opened_on)}}</span></div></section><div class="quick-actions"><button class="btn btn-outline-primary" data-bs-toggle="collapse" data-bs-target="#actionForm"><i class="bx bx-plus"></i> Registrar intervención</button><button class="btn btn-outline-primary" @click="generateReport"><i class="bx bx-file"></i> Generar ficha maestra</button><button v-if="api.can('social_work.reports.export')" class="btn btn-outline-primary" @click="downloadSocialCaseMaster(caseData)"><i class="bx bx-download"></i> Descargar PDF</button><button v-if="caseData.status!=='cerrado'" class="btn btn-outline-danger" @click="closeCase"><i class="bx bx-lock"></i> Cerrar caso</button></div>
    <section id="actionForm" class="collapse sw-card mb-3"><h2>Nueva intervención</h2><div class="row g-2"><div class="col-md-3"><label>Registro</label><select v-model="actionForm.kind" class="form-select"><option value="entrevista">Entrevista</option><option value="accion">Acción</option><option value="visita_domiciliaria">Visita domiciliaria</option><option value="llamado">Llamado telefónico</option><option value="accion_familiar">Acción familiar</option><option value="seguimiento">Seguimiento</option></select></div><div class="col-md-3"><label>Fecha</label><input v-model="actionForm.activity_date" type="date" class="form-control"></div><div class="col-md-3"><label>Estado</label><select v-model="actionForm.status" class="form-select"><option>borrador</option><option>finalizada</option><option>anulada</option></select></div><div class="col-md-3"><label>Confidencialidad</label><select v-model="actionForm.confidentiality" class="form-select"><option>interno</option><option>restringido</option><option>altamente_restringido</option></select></div><div class="col-12"><label>Objetivo *</label><input v-model="actionForm.objective" class="form-control"></div><div class="col-12"><label>Descripción</label><textarea v-model="actionForm.description" class="form-control" rows="3"></textarea></div><div class="col-md-8"><label>Próxima acción</label><input v-model="actionForm.next_action" class="form-control"></div><div class="col-md-4"><label>Fecha límite</label><input v-model="actionForm.due_at" type="datetime-local" class="form-control"></div><div class="col-12"><button class="btn btn-primary" @click="createAction">Guardar intervención</button></div></div></section>
    <div class="row g-3"><div class="col-xl-8"><section class="sw-card"><h2>Cronología resumida</h2><div v-for="i in caseData.interventions" :key="i.id" class="timeline-item"><i class="bx bx-check-circle"></i><div><strong>{{statusLabel(i.kind)}} · {{i.objective}}</strong><span>{{fmt(i.activity_date)}} · {{i.responsible?.name||'Sin responsable'}}</span><p>{{i.result||i.description||'Sin resumen general.'}}</p></div></div><p v-if="!caseData.interventions?.length" class="empty">Aún no existen intervenciones.</p></section></div><div class="col-xl-4"><section class="sw-card mb-3"><h2>Resumen</h2><dl><dt>Motivo</dt><dd>{{caseData.reason}}</dd><dt>Próximo hito</dt><dd>{{caseData.next_milestone||'Sin definir'}}</dd><dt>Fecha límite</dt><dd>{{fmt(caseData.due_at)}}</dd><dt>Reaperturas</dt><dd>{{caseData.reopen_count}}</dd></dl></section><section class="sw-card"><h2>Alertas</h2><div v-for="a in caseData.alerts" :key="a.id" class="alert-row"><i class="bx bx-bell"></i><span><strong>{{statusLabel(a.type)}}</strong><small>{{a.reason}}</small></span></div><p v-if="!caseData.alerts?.length" class="empty">Sin alertas.</p></section></div></div>
  </template>

  <template v-else-if="pathSection==='student-detail' && caseData"><section class="case-hero"><div><span class="case-code">Ficha social</span><h2>{{studentName(caseData.student)}}</h2><p>{{caseData.student.rut}} · Datos maestros no duplicados</p></div><div class="case-facts"><span><small>Casos activos</small>{{caseData.cases.filter(c=>!['cerrado','anulado'].includes(c.status)).length}}</span><span><small>Programas</small>{{caseData.programs.length}}</span><span><small>Alertas</small>{{caseData.alerts.filter(a=>!['resuelta','descartada'].includes(a.status)).length}}</span></div></section><div class="row g-3"><div class="col-lg-6"><section class="sw-card"><h2>Casos psicosociales</h2><button v-for="c in caseData.cases" :key="c.id" class="record-link" @click="go(`/social-work/cases/${c.id}`)"><span><strong>{{c.code}} · {{c.title}}</strong><small>{{statusLabel(c.status)}} · {{c.responsible?.name||'Sin asignar'}}</small></span><RiskBadge :level="c.risk_level"/></button><p v-if="!caseData.cases.length" class="empty">Sin casos autorizados.</p></section></div><div class="col-lg-6"><section class="sw-card"><h2>Programas y beneficios</h2><div v-for="p in caseData.programs" :key="p.id" class="stat-row"><span>{{p.program_type?.name}}</span><span class="soft-badge">{{p.school_year}} · {{p.status}}</span></div><p v-if="!caseData.programs.length" class="empty">Sin programas.</p></section><section class="sw-card mt-3"><h2>Medidas de protección</h2><div v-for="m in caseData.protection_measures" :key="m.id" class="alert-row"><i class="bx bx-shield-quarter"></i><span><strong>{{m.measure_type}}</strong><small>{{m.status}} · desde {{fmt(m.starts_on)}}</small></span></div><p v-if="!caseData.protection_measures.length" class="empty">Sin medidas visibles.</p></section></div></div></template>

  <section v-else-if="pathSection==='settings'" class="sw-card"><div class="section-title"><h2>Plantillas institucionales</h2><span>Las versiones utilizadas no se modifican retrospectivamente.</span></div><div v-for="t in rows" :key="t.id" class="template-row"><i class="bx bx-file-blank"></i><span><strong>{{t.name}}</strong><small>{{statusLabel(t.type)}} · Versión {{t.versions?.[0]?.version||1}} · {{t.versions?.[0]?.status}}</small></span></div><p v-if="!rows.length" class="empty">Ejecuta el seeder de Trabajo Social para crear borradores base.</p><div class="draft-warning"><i class="bx bx-info-circle"></i><div><strong>Formatos pendientes de validación institucional</strong><p>Entrevista, visita domiciliaria, llamado telefónico, derivación, acta JUNAEB e informe social permanecen marcados como borradores base.</p></div></div></section>
</div></Layout>
</template>

